}

/* Efek garis emas di header */
.info-header-boba::before {
    content: '';
    position: absolute;
    bottom: -3px;
    left: 25%;
    width: 50%;
    height: 3px;
    background: linear-gradient(90deg, transparent, var(--gold-light), transparent);
    border-radius: 3px;
}

.info-header-boba::after {
    content: '✦';
    position: absolute;
    right: 30px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--gold-primary);
    font-size: 20px;
    opacity: 0.5;
}

/* === ROWS === */
.info-row-boba {
    display: flex;
